import re

_PAIR = re.compile(r"([1-9][0-9]*)([^0-9])", re.DOTALL)
_WHOLE = re.compile(r"(?:[1-9][0-9]*[^0-9])*", re.DOTALL)


def encode(s):
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        j = i + 1
        while j < n and s[j] == ch:
            j += 1
        out.append(str(j - i) + ch)
        i = j
    return "".join(out)


def decode(code):
    if _WHOLE.fullmatch(code) is None:
        raise ValueError("malformed run-length code")
    return "".join(ch * int(num) for num, ch in _PAIR.findall(code))

