def format_size(n):
    if n < 1024:
        return str(n) + " B"
    for name, size in _UNITS:
        if n >= size:
            tenths = (n * 10 + size // 2) // size
            whole, frac = divmod(tenths, 10)
            return "{}.{} {}".format(whole, frac, name)
