def to_snake(name):
    padded = " " + name + " "
    pieces = []
    for i in range(1, len(padded) - 1):
        prev, ch, nxt = padded[i - 1], padded[i], padded[i + 1]
        if i > 1 and ch.isupper():
            if prev.islower() or prev.isdigit():
                pieces.append("_")
            elif prev.isupper() and nxt.islower():
                pieces.append("_")
        pieces.append(ch)
    return "".join(pieces).lower()

